import numpy as np, torch, model
net=model.load(); neg=model.negatives()
def dec(X,cc):
    r=model.decode(net,X.astype(np.float32),np.full(len(X),cc,dtype=np.float32))
    return np.asarray(r[0] if isinstance(r,tuple) else r)
b=model.basin(13); print('eps',b['eps'],'bad',b['bad'],'thr',b['thr'])
th=np.linspace(-np.pi,np.pi,72,endpoint=False)
for cc in [0.0,0.1,0.2,0.5,0.8]:
  for R in [0.6,1.5]:
    X=np.stack([np.cos(th),np.sin(th)],1)*R
    A=dec(X,cc)
    ang=np.degrees(np.arctan2(A[:,1],A[:,0])).round(0).astype(int)
    print(cc,R, ' '.join(f'{int(np.degrees(t))}:{a}' for t,a in zip(th[::3],ang[::3])))

import numpy as np, torch, model
torch.manual_seed(0)
net=model.load(); neg=model.negatives(); w=np.load('contrast_c3_blocks.1_k12.npy').astype(np.float32); b0=-12.6728
uids=list(neg['uid']); 
ex=[uids.index(u) for u in (78,114,129,26,35,80,124,146,148,183)]
for i in ex: print(uids[i], round(float(neg['c'][i]),3), neg['a'][i].round(2))
def mk(delta,klo,khi):
    return model._Graft(dict(layer='out',det_source='blocks.1',det_w=torch.tensor(w),det_b=b0,det_thr=0.0,k_range=(klo,khi),
        src='t',w_in=torch.zeros(1,1),b_in=torch.ones(1),act='linear',w_out=torch.tensor(delta,dtype=torch.float32).reshape(2,1)))
N=256
noise=torch.randn(N,2)
def resid(net):
    r=[]
    for i in ex:
        a=model.decode(net,noise,torch.full((N,),float(neg['c'][i])))
        r.append(model.in_basin(i,a.numpy()).mean())
    return np.array(r)
cg=torch.rand(4096); ng=torch.randn(4096,2)
base=model.decode(net,ng,cg).numpy()
print('base',resid(net).round(3))
for mag in [4,8]:
  for ang in [0,1,7]:
    th=ang*np.pi/4; dv=[-mag*np.cos(th),-mag*np.sin(th)]
    for kr in [(0,13),(8,16)]:
        net.grafts=[mk(dv,*kr)]
        r=resid(net); a=model.decode(net,ng,cg).numpy()
        mv=np.linalg.norm(a-base,axis=1)>0.3
        print(mag,ang,kr,r.round(2),'mean',r.mean().round(3),'drift',mv.mean().round(3))
    net.grafts=[]

